$ErrorActionPreference='Stop';$root=Join-Path $PSScriptRoot '..';$tmp=Join-Path $env:TEMP ('blueprint-pos-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $tmp|Out-Null
try{$before=(Get-FileHash (Join-Path $root 'catalogs/blueprint-catalog-v2.json') -Algorithm SHA256).Hash; & (Join-Path $PSScriptRoot 'New-BlueprintPreview.ps1') -BlueprintId bp-bc-basic -OutputPath $tmp; $a=Get-FileHash (Join-Path $tmp 'preview.json') -Algorithm SHA256; Remove-Item (Join-Path $tmp 'preview.json'); & (Join-Path $PSScriptRoot 'New-BlueprintPreview.ps1') -BlueprintId bp-bc-basic -OutputPath $tmp; $b=Get-FileHash (Join-Path $tmp 'preview.json') -Algorithm SHA256;if($a.Hash -ne $b.Hash){throw 'BLUEPRINT_IDEMPOTENCY_FAILED'}; & (Join-Path $PSScriptRoot 'Test-BlueprintCatalogV2.ps1') -CatalogPath (Join-Path $root 'catalogs/blueprint-catalog-v2.json');$after=(Get-FileHash (Join-Path $root 'catalogs/blueprint-catalog-v2.json') -Algorithm SHA256).Hash;if($before -ne $after){throw 'BLUEPRINT_DIRECT_MUTATION'};Write-Output 'PASS: Blueprint-Katalog positiv, idempotent und read-only.'}finally{if(Test-Path $tmp){Remove-Item -LiteralPath $tmp -Recurse -Force}}
